import java.math.BigDecimal;
import java.util.Objects;

public final class TestSupport {
    private TestSupport() {}

    public static void eq(Object expected, Object actual, String what) {
        if (!Objects.equals(expected, actual)) {
            throw new AssertionError(what + " | expected <" + expected + "> but was <" + actual + ">");
        }
    }

    public static void check(boolean condition, String what) {
        if (!condition) throw new AssertionError(what);
    }

    public static void money(String expected, BigDecimal actual, String what) {
        BigDecimal wanted = new BigDecimal(expected);
        if (actual == null || actual.compareTo(wanted) != 0) {
            throw new AssertionError(what + " | expected <" + wanted + "> but was <" + actual + ">");
        }
    }

    public static void near(double expected, double actual, double epsilon, String what) {
        if (Math.abs(expected - actual) > epsilon) {
            throw new AssertionError(what + " | expected <" + expected + "> but was <" + actual + ">");
        }
    }

    public interface Block {
        void run() throws Exception;
    }

    public static <T extends Throwable> T throwsType(Class<T> type, Block block, String what) {
        try {
            block.run();
        } catch (Throwable error) {
            if (type.isInstance(error)) return type.cast(error);
            throw new AssertionError(what + " | expected " + type.getSimpleName()
                    + " but got " + error.getClass().getSimpleName() + ": " + error.getMessage(), error);
        }
        throw new AssertionError(what + " | expected " + type.getSimpleName() + " but nothing was thrown");
    }
}

