public class LruEvictionTest {
    public static void main(String[] args) {
        var cache = new LruCache<String, Integer>(2);
        cache.put("A", 1);
        cache.put("B", 2);
        TestSupport.eq(Integer.valueOf(1), cache.get("A"), "read A");
        cache.put("C", 3);
        TestSupport.check(cache.containsKey("A"), "A should survive because it was read");
        TestSupport.check(!cache.containsKey("B"), "B should be evicted as least recently used");
        TestSupport.check(cache.containsKey("C"), "C should be present");
        System.out.println("PASS: reading a key refreshes it before eviction");
    }
}

public class UpdateExistingTest {
    public static void main(String[] args) {
        var cache = new LruCache<String, Integer>(2);
        cache.put("A", 1);
        cache.put("B", 2);
        cache.put("A", 9);
        TestSupport.eq(2, cache.size(), "size");
        TestSupport.eq(Integer.valueOf(9), cache.get("A"), "updated A");
        TestSupport.eq(Integer.valueOf(2), cache.get("B"), "B survives");
        System.out.println("PASS: updating an existing key does not grow the cache");
    }
}

public class MissingKeyTest {
    public static void main(String[] args) {
        var cache = new LruCache<String, Integer>(2);
        TestSupport.eq(null, cache.get("missing"), "missing key");
        TestSupport.check(!cache.containsKey("missing"), "missing key absent");
        System.out.println("PASS: missing keys return null");
    }
}

public class ConstructorTest {
    public static void main(String[] args) {
        TestSupport.throwsType(IllegalArgumentException.class, () -> new LruCache<String, Integer>(0), "zero capacity");
        TestSupport.throwsType(IllegalArgumentException.class, () -> new LruCache<String, Integer>(-1), "negative capacity");
        System.out.println("PASS: invalid capacities are rejected");
    }
}

