import java.util.*;

public class ResizeTest {
    public static void main(String[] args) {
        var cache = new LruCache<String, Integer>(3);
        cache.put("A", 1);
        cache.put("B", 2);
        cache.put("C", 3);
        cache.get("A");
        cache.resize(2);
        TestSupport.eq(2, cache.size(), "new size");
        TestSupport.check(cache.containsKey("A"), "A was read most recently");
        TestSupport.check(cache.containsKey("C"), "C is next most recent");
        TestSupport.check(!cache.containsKey("B"), "B is least recent");
        TestSupport.eq(List.of("A", "C"), cache.keysByRecency(), "order after resize");
        System.out.println("PASS: resize evicts least recently used entries");
    }
}

public class ResizeInvalidTest {
    public static void main(String[] args) {
        var cache = new LruCache<String, Integer>(2);
        cache.put("A", 1);
        cache.put("B", 2);
        TestSupport.throwsType(IllegalArgumentException.class, () -> cache.resize(0), "zero resize");
        TestSupport.eq(2, cache.size(), "size unchanged");
        TestSupport.check(cache.containsKey("A") && cache.containsKey("B"), "entries unchanged");
        System.out.println("PASS: invalid resize is rejected and leaves the cache intact");
    }
}

